Action: run_sql({'query': "SELECT \n    ek.slchd_establishment_key,\n    ek.name,\n    ek.address,\n    ek.city,\n    i.inspection_id,\n    i.inspection_date,\n    it.description as inspection_type,\n    i.inspection_score,\n    COUNT(v.violation_id) as total_violations_cited,\n    SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) as critical_violations\nFROM establishment_keys ek\nJOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\nLEFT JOIN inspection_types it ON i.inspection_type_id = it.inspection_type_id\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nWHERE ek.name = 'IN N OUT BURGER'\nGROUP BY ek.slchd_establishment_key, ek.name, ek.address, ek.city, i.inspection_id, i.inspection_date, it.description, i.inspection_score\nORDER BY ek.city, i.inspection_date DESC;"})

